using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace Media.DBContext.Models;

/// <summary>
/// Represents one entry in the federation audit log.
/// </summary>
[Table("federation_audit_log")]
public class FederationAuditEntry
{
  /// <summary>
  /// Primary key. Autogenerated.
  /// </summary>
  [Key]
  public Guid EntryId { get; set; }

  /// <summary>
  /// Date when the entry was created.
  /// </summary>
  public DateTime Timestamp { get; set; }

  /// <summary>
  /// The action which was performed.
  /// </summary>
  public int Action { get; set; }

  /// <summary>
  /// The status of the action.
  /// </summary>
  public int Status { get; set; }

  /// <summary>
  /// The instance the action originated from.
  /// </summary>
  public string Source { get; set; } = null!;

  /// <summary>
  /// The instance the action targeted.
  /// </summary>
  public string Target { get; set; } = null!;

  /// <summary>
  /// The id of the related transaction if available.
  /// </summary>
  public Guid? TransactionId { get; set; }

  /// <summary>
  /// The ids of the affected records.
  /// </summary>
  [Column(TypeName = "jsonb")]
  public List<Guid> RecordIds { get; set; } = [];

  /// <summary>
  /// Additional information or the error message.
  /// </summary>
  public string? Message { get; set; }
}
